CREATE TABLE IF NOT EXISTS punch_segments (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, employee_id TEXT NOT NULL, job_id TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT, gross_duration INTEGER, deduction_duration INTEGER, payable_duration INTEGER, source TEXT NOT NULL, client_request_id TEXT NOT NULL, gps_context TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(employee_id) REFERENCES employees(id), FOREIGN KEY(job_id) REFERENCES jobs(id));
CREATE UNIQUE INDEX IF NOT EXISTS idx_punch_client_request ON punch_segments(company_id,client_request_id);
CREATE INDEX IF NOT EXISTS idx_punch_employee_time ON punch_segments(company_id,employee_id,start_time);
CREATE TABLE IF NOT EXISTS shortcut_definitions (id TEXT PRIMARY KEY, company_id TEXT, shortcut_key TEXT NOT NULL, label TEXT NOT NULL, icon_key TEXT NOT NULL, route_key TEXT NOT NULL, required_permission TEXT, allowed_roles TEXT NOT NULL, requires_active_job INTEGER NOT NULL DEFAULT 0, module_key TEXT NOT NULL, is_enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_shortcut_definition_key ON shortcut_definitions(company_id,shortcut_key);
CREATE TABLE IF NOT EXISTS user_home_layouts (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, user_id TEXT NOT NULL, employee_id TEXT NOT NULL, role_snapshot TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_home_layout ON user_home_layouts(company_id,user_id);
CREATE TABLE IF NOT EXISTS user_home_layout_items (id TEXT PRIMARY KEY, user_home_layout_id TEXT NOT NULL, shortcut_key TEXT NOT NULL, position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 8), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(user_home_layout_id) REFERENCES user_home_layouts(id));
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_home_shortcut_unique ON user_home_layout_items(user_home_layout_id,shortcut_key);
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_home_position_unique ON user_home_layout_items(user_home_layout_id,position);
CREATE TABLE IF NOT EXISTS company_home_creation_layouts (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, role_type TEXT NOT NULL CHECK(role_type IN ('EMPLOYEE','TEAM_LEAD')), layout_version INTEGER NOT NULL, is_current INTEGER NOT NULL DEFAULT 1, created_by_user_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(created_by_user_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_company_home_current ON company_home_creation_layouts(company_id,role_type,is_current);
CREATE TABLE IF NOT EXISTS company_home_creation_layout_items (id TEXT PRIMARY KEY, layout_id TEXT NOT NULL, shortcut_key TEXT NOT NULL, position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 8), created_at TEXT NOT NULL, FOREIGN KEY(layout_id) REFERENCES company_home_creation_layouts(id));
CREATE UNIQUE INDEX IF NOT EXISTS idx_company_home_shortcut_unique ON company_home_creation_layout_items(layout_id,shortcut_key);
CREATE TABLE IF NOT EXISTS weather_snapshots (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, job_id TEXT, location_label TEXT NOT NULL, latitude REAL, longitude REAL, temperature REAL NOT NULL, condition TEXT NOT NULL, rain_probability REAL, wind_speed REAL, weather_alert TEXT, observed_at TEXT NOT NULL, expires_at TEXT, FOREIGN KEY(job_id) REFERENCES jobs(id));
CREATE INDEX IF NOT EXISTS idx_weather_job_time ON weather_snapshots(company_id,job_id,observed_at);
CREATE TABLE IF NOT EXISTS job_progress_reports (id TEXT PRIMARY KEY, company_id TEXT NOT NULL, job_id TEXT NOT NULL, chef_employee_id TEXT NOT NULL, punch_segment_id TEXT, report_date TEXT NOT NULL, summary TEXT, progress_percent REAL, work_completed TEXT, material_missing TEXT, blockers TEXT, potential_extra TEXT, needs_for_tomorrow TEXT, note TEXT, submitted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(job_id) REFERENCES jobs(id), FOREIGN KEY(chef_employee_id) REFERENCES employees(id), FOREIGN KEY(punch_segment_id) REFERENCES punch_segments(id));
CREATE INDEX IF NOT EXISTS idx_progress_job_date ON job_progress_reports(company_id,job_id,report_date);
